import subprocess, json, sys
args = {"content": "Follow up with Maya if she's not there by 6:30 PM.", "reminder_timestamp": 1803033000.0}
result = subprocess.run(
    ["python", "/workspace/skills/toolsandbox-assistant/tools.py", "add_reminder", "--json", json.dumps(args)],
    capture_output=True, text=True, timeout=20
)
print(result.stdout.strip())
if result.returncode != 0:
    print("STDERR:", result.stderr.strip())

import sqlite3, json
conn = sqlite3.connect('/workspace/world.db')
tables = [r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()]
results = {"tables": tables}
for t in tables:
    if 'remind' in t.lower():
        rows = conn.execute(f"SELECT * FROM {t}").fetchall()
        cols = [d[0] for d in conn.execute(f"SELECT * FROM {t}").description]
        results[t] = {"columns": cols, "rows": [list(r) for r in rows]}
conn.close()
with open('/workspace/db_out.txt', 'w') as f:
    f.write(json.dumps(results, indent=2))
